301	/// Inject credentials for a channel based on naming convention.
302	///
303	/// Looks for secrets matching the pattern `{channel_name}_*` and injects them
304	/// as credential placeholders (e.g., `telegram_bot_token` -> `{TELEGRAM_BOT_TOKEN}`).
305	///
306	/// Falls back to environment variables starting with the uppercase channel name
307	/// prefix (e.g., `TELEGRAM_` for channel `telegram`) for missing credentials.
308	///
309	/// Returns the number of credentials injected.
310	pub async fn inject_channel_credentials(
311	    channel: &Arc<WasmChannel>,
312	    secrets: Option<&dyn SecretsStore>,
313	    channel_name: &str,
314	    owner_id: &str,
315	) -> anyhow::Result<usize> {
316	    if channel_name.trim().is_empty() {
317	        return Ok(0);
318	    }
319	
320	    let mut count = 0;
321	    let mut injected_placeholders = HashSet::new();
322	
323	    // 1. Try injecting from persistent secrets store if available
324	    if let Some(secrets) = secrets {
325	        let all_secrets = secrets
326	            .list(owner_id)
327	            .await
328	            .map_err(|e| anyhow::anyhow!("Failed to list secrets: {}", e))?;
329	
330	        let prefix = format!("{}_", channel_name.to_ascii_lowercase());
331	
332	        for secret_meta in all_secrets {
333	            if !secret_meta.name.to_ascii_lowercase().starts_with(&prefix) {
334	                continue;
335	            }
336	
337	            let decrypted = match secrets.get_decrypted(owner_id, &secret_meta.name).await {
338	                Ok(d) => d,
339	                Err(e) => {
340	                    tracing::warn!(
341	                        secret = %secret_meta.name,
342	                        error = %e,
343	                        "Failed to decrypt secret for channel credential injection"
344	                    );
345	                    continue;
346	                }
347	            };
348	
349	            let placeholder = secret_meta.name.to_uppercase();
350	
351	            tracing::debug!(
352	                channel = %channel_name,
353	                secret = %secret_meta.name,
354	                placeholder = %placeholder,
355	                "Injecting credential"
356	            );
357	
358	            channel
359	                .set_credential(&placeholder, decrypted.expose().to_string())
360	                .await;
361	            injected_placeholders.insert(placeholder);
362	            count += 1;
363	        }
364	    }
365	
366	    // 2. Fall back to environment variables for credentials not in the secrets store.
367	    // Only env vars starting with the channel's uppercase prefix are allowed
368	    // (e.g., TELEGRAM_ for channel "telegram") to prevent reading unrelated host
369	    // credentials like AWS_SECRET_ACCESS_KEY.
370	    let prefix = format!("{}_", channel_name.to_ascii_uppercase());
371	    let caps = channel.capabilities();
372	    if let Some(ref http_cap) = caps.tool_capabilities.http {
373	        for cred_mapping in http_cap.credentials.values() {
374	            let placeholder = cred_mapping.secret_name.to_uppercase();
375	            if injected_placeholders.contains(&placeholder) {
376	                continue;
377	            }
378	            if !placeholder.starts_with(&prefix) {
379	                tracing::warn!(
380	                    channel = %channel_name,
381	                    placeholder = %placeholder,
382	                    "Ignoring non-prefixed credential placeholder in environment fallback"
383	                );
384	                continue;
385	            }
386	            if let Ok(env_value) = std::env::var(&placeholder)
387	                && !env_value.is_empty()
388	            {
389	                tracing::debug!(
390	                    channel = %channel_name,
391	                    placeholder = %placeholder,
392	                    "Injecting credential from environment variable"
393	                );
394	                channel.set_credential(&placeholder, env_value).await;
395	                count += 1;
396	            }
397	        }
398	    }
399	
400	    Ok(count)
401	}
