403	async fn load_channel_setup_field_overrides(
404	    settings_store: Option<&Arc<dyn crate::db::SettingsStore>>,
405	    owner_id: &str,
406	    channel_name: &str,
407	    capabilities_file: Option<&crate::channels::wasm::ChannelCapabilitiesFile>,
408	) -> std::collections::HashMap<String, serde_json::Value> {
409	    let mut overrides = std::collections::HashMap::new();
410	    let Some(store) = settings_store else {
411	        return overrides;
412	    };
413	    let Some(cap_file) = capabilities_file else {
414	        return overrides;
415	    };
416	
417	    let key = format!("extensions.{channel_name}.setup_fields");
418	    let saved_fields = match store.get_setting(owner_id, &key).await {
419	        Ok(Some(value)) => {
420	            serde_json::from_value::<std::collections::HashMap<String, String>>(value)
421	                .unwrap_or_default()
422	        }
423	        _ => std::collections::HashMap::new(),
424	    };
425	
426	    for field in &cap_file.setup.required_fields {
427	        if let Some(value) = saved_fields.get(&field.name)
428	            && !value.trim().is_empty()
429	        {
430	            overrides.insert(field.name.clone(), serde_json::Value::String(value.clone()));
431	            continue;
432	        }
433	
434	        if let Some(setting_path) = field.setting_path.as_deref()
435	            && let Ok(Some(value)) = store.get_setting(owner_id, setting_path).await
436	            && setting_value_is_present(&value)
437	        {
438	            overrides.insert(field.name.clone(), value);
439	        }
440	    }
441	
442	    overrides
443	}
444	
445	fn setting_value_is_present(value: &serde_json::Value) -> bool {
446	    match value {
447	        serde_json::Value::Null => false,
448	        serde_json::Value::String(s) => !s.trim().is_empty(),
449	        serde_json::Value::Array(a) => !a.is_empty(),
450	        serde_json::Value::Object(o) => !o.is_empty(),
451	        _ => true,
452	    }
453	}
