455	/// Inject channel-specific secrets into the config JSON.
456	///
457	/// Some channels (e.g., Feishu) need raw credential values in their config
458	/// because they perform token exchanges that require secrets in the HTTP
459	/// request body. The standard credential injection system only replaces
460	/// placeholders in URLs and headers, so this function fills config fields
461	/// that map to secret names.
462	///
463	/// Mapping: for a channel named "feishu", secrets `feishu_app_id` and
464	/// `feishu_app_secret` are injected as config keys `app_id` and `app_secret`.
465	async fn inject_channel_secrets_into_config(
466	    channel_name: &str,
467	    secrets_store: &Option<Arc<dyn SecretsStore + Send + Sync>>,
468	    owner_id: &str,
469	    config_updates: &mut std::collections::HashMap<String, serde_json::Value>,
470	) {
471	    // Map of (config_key, secret_name) pairs per channel.
472	    let secret_config_mappings: &[(&str, &str)] = match channel_name {
473	        "feishu" => &[
474	            ("app_id", "feishu_app_id"),
475	            ("app_secret", "feishu_app_secret"),
476	        ],
477	        "xmpp" => &[("xmpp_password", "xmpp_password")],
478	        _ => return,
479	    };
480	
481	    let Some(secrets) = secrets_store else {
482	        return;
483	    };
484	
485	    for &(config_key, secret_name) in secret_config_mappings {
486	        match secrets.get_decrypted(owner_id, secret_name).await {
487	            Ok(decrypted) => {
488	                config_updates.insert(
489	                    config_key.to_string(),
490	                    serde_json::Value::String(decrypted.expose().to_string()),
491	                );
492	                tracing::debug!(
493	                    channel = %channel_name,
494	                    config_key = %config_key,
495	                    "Injected secret into channel config"
496	                );
497	            }
498	            Err(_) => {
499	                // Also try environment variable fallback.
500	                let env_name = secret_name.to_uppercase();
501	                if let Ok(val) = std::env::var(&env_name)
502	                    && !val.is_empty()
503	                {
504	                    config_updates.insert(config_key.to_string(), serde_json::Value::String(val));
505	                    tracing::debug!(
506	                        channel = %channel_name,
507	                        config_key = %config_key,
508	                        "Injected secret from env into channel config"
509	                    );
510	                }
511	            }
512	        }
513	    }
514	}
