196	    /// Load all WASM tools from a directory.
197	    ///
198	    /// Scans the directory for `*.wasm` files and loads each one, looking for
199	    /// a matching `*.capabilities.json` sidecar file.
200	    ///
201	    /// # Directory Layout
202	    ///
203	    /// ```text
204	    /// tools/
205	    /// ├── slack.wasm                  <- Tool WASM component
206	    /// ├── slack.capabilities.json     <- Capabilities (optional)
207	    /// ├── github.wasm
208	    /// └── github.capabilities.json
209	    /// ```
210	    ///
211	    /// Tools without a capabilities file get no permissions (default deny).
212	    pub async fn load_from_dir(&self, dir: &Path) -> Result<LoadResults, WasmLoadError> {
213	        match fs::metadata(dir).await {
214	            Ok(meta) if meta.is_dir() => {}
215	            Ok(_) => {
216	                return Err(WasmLoadError::Io(std::io::Error::new(
217	                    std::io::ErrorKind::NotADirectory,
218	                    format!("{} is not a directory", dir.display()),
219	                )));
220	            }
221	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
222	                return Ok(LoadResults::default());
223	            }
224	            Err(e) => return Err(WasmLoadError::Io(e)),
225	        }
226	
227	        // Handle TOCTOU: if read_dir fails with NotFound, treat as empty
228	        let mut entries = match fs::read_dir(dir).await {
229	            Ok(entries) => entries,
230	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
231	                return Ok(LoadResults::default());
232	            }
233	            Err(e) => return Err(WasmLoadError::Io(e)),
234	        };
235	
236	        let mut results = LoadResults::default();
237	        let mut tool_entries = Vec::new();
238	
239	        while let Some(entry) = entries.next_entry().await? {
240	            let path = entry.path();
241	
242	            if path.extension().and_then(|e| e.to_str()) != Some("wasm") {
243	                continue;
244	            }
245	
246	            let name = match path.file_stem().and_then(|s| s.to_str()) {
247	                Some(n) => n.to_string(),
248	                None => {
249	                    results.errors.push((
250	                        path.clone(),
251	                        WasmLoadError::InvalidName("invalid filename".to_string()),
252	                    ));
253	                    continue;
254	                }
255	            };
256	
257	            let cap_path = path.with_extension("capabilities.json");
258	            let has_cap = cap_path.exists();
259	            tool_entries.push((name, path, if has_cap { Some(cap_path) } else { None }));
260	        }
261	
262	        // Load all tools in parallel (file I/O + WASM compilation + registration)
263	        let load_futures = tool_entries
264	            .iter()
265	            .map(|(name, path, cap_path)| self.load_from_files(name, path, cap_path.as_deref()));
266	
267	        let load_results = futures::future::join_all(load_futures).await;
268	
269	        for ((name, path, _), result) in tool_entries.into_iter().zip(load_results) {
270	            match result {
271	                Ok(()) => {
272	                    results.loaded.push(name);
273	                }
274	                Err(e) => {
275	                    tracing::error!(
276	                        name = name,
277	                        path = %path.display(),
278	                        error = %e,
279	                        "Failed to load WASM tool"
280	                    );
281	                    results.errors.push((path, e));
282	                }
283	            }
284	        }
285	
286	        if !results.loaded.is_empty() {
287	            tracing::debug!(
288	                count = results.loaded.len(),
289	                tools = ?results.loaded,
290	                "Loaded WASM tools from directory"
291	            );
292	        }
293	
294	        Ok(results)
295	    }
