409	/// Extract OAuth refresh configuration from a parsed capabilities file.
410	///
411	/// Returns `None` if there's no `auth.oauth` section or if the client_id
412	/// can't be resolved from any source (inline, env var, or built-in defaults).
413	///
414	/// Fallback chain for client_id:
415	///   `oauth.client_id` > env var (`oauth.client_id_env`) > `builtin_credentials()`
416	fn resolve_oauth_refresh_config(cap_file: &CapabilitiesFile) -> Option<OAuthRefreshConfig> {
417	    let auth = cap_file.auth.as_ref()?;
418	    let oauth = auth.oauth.as_ref()?;
419	
420	    let builtin = crate::cli::oauth_defaults::builtin_credentials(&auth.secret_name);
421	    let exchange_proxy_url = crate::cli::oauth_defaults::exchange_proxy_url();
422	
423	    let client_id = oauth
424	        .client_id
425	        .clone()
426	        .or_else(|| {
427	            oauth
428	                .client_id_env
429	                .as_ref()
430	                .and_then(|env| std::env::var(env).ok())
431	        })
432	        .or_else(|| builtin.as_ref().map(|c| c.client_id.to_string()))?;
433	
434	    let client_secret = oauth
435	        .client_secret
436	        .clone()
437	        .or_else(|| {
438	            oauth
439	                .client_secret_env
440	                .as_ref()
441	                .and_then(|env| std::env::var(env).ok())
442	        })
443	        .or_else(|| builtin.as_ref().map(|c| c.client_secret.to_string()));
444	    let client_secret = crate::cli::oauth_defaults::hosted_proxy_client_secret(
445	        &client_secret,
446	        builtin.as_ref(),
447	        exchange_proxy_url.is_some(),
448	    );
449	    let gateway_token = crate::config::helpers::env_or_override("GATEWAY_AUTH_TOKEN")
450	        .map(|token| token.trim().to_string())
451	        .filter(|token| !token.is_empty());
452	
453	    Some(OAuthRefreshConfig {
454	        token_url: oauth.token_url.clone(),
455	        client_id,
456	        client_secret,
457	        exchange_proxy_url,
458	        gateway_token,
459	        secret_name: auth.secret_name.clone(),
460	        provider: auth.provider.clone(),
461	    })
462	}
