531	/// Discover WASM tools available as build artifacts in `tools-src/`.
532	///
533	/// Scans each subdirectory for:
534	/// - `tools-src/<name>/target/wasm32-wasip2/release/<crate_name>_tool.wasm`
535	/// - `tools-src/<name>/<name>-tool.capabilities.json`
536	///
537	/// Returns a map of install-name (e.g. "gmail-tool") to paths.
538	pub async fn discover_dev_tools() -> Result<HashMap<String, DiscoveredTool>, std::io::Error> {
539	    let src_dir = tools_src_dir();
540	    let mut tools = HashMap::new();
541	
542	    if !src_dir.is_dir() {
543	        return Ok(tools);
544	    }
545	
546	    let mut entries = fs::read_dir(&src_dir).await?;
547	    while let Some(entry) = entries.next_entry().await? {
548	        let path = entry.path();
549	        if !path.is_dir() {
550	            continue;
551	        }
552	
553	        let dir_name = match path.file_name().and_then(|n| n.to_str()) {
554	            Some(n) => n.to_string(),
555	            None => continue,
556	        };
557	
558	        // Convention: crate name uses underscores, directory uses hyphens
559	        let crate_name = dir_name.replace('-', "_");
560	        let install_name = format!("{}-tool", dir_name);
561	
562	        let wasm_path = wasm_artifact_path(&path, &format!("{}_tool", crate_name));
563	
564	        if !wasm_path.exists() {
565	            continue;
566	        }
567	
568	        let caps_path = path.join(format!("{}-tool.capabilities.json", dir_name));
569	
570	        tools.insert(
571	            install_name,
572	            DiscoveredTool {
573	                wasm_path,
574	                capabilities_path: if caps_path.exists() {
575	                    Some(caps_path)
576	                } else {
577	                    None
578	                },
579	            },
580	        );
581	    }
582	
583	    Ok(tools)
584	}
