1	//! Serde structs for extension registry manifests.
2	//!
3	//! Each manifest describes a single extension (tool or channel) with its source
4	//! location, build artifacts, authentication requirements, and tags.
5	
6	use serde::{Deserialize, Serialize};
7	
8	use crate::extensions::{AuthHint, ExtensionKind, ExtensionSource, RegistryEntry};
9	
10	/// A single extension manifest loaded from `registry/{tools,channels,mcp-servers}/<name>.json`.
11	#[derive(Debug, Clone, Serialize, Deserialize)]
12	pub struct ExtensionManifest {
13	    /// Unique identifier (matches crate name stem, e.g. "slack").
14	    pub name: String,
15	
16	    /// Human-readable name (e.g. "Slack").
17	    pub display_name: String,
18	
19	    /// Whether this is a tool, channel, or MCP server.
20	    pub kind: ManifestKind,
21	
22	    /// Semver version from Cargo.toml. Optional for MCP server manifests.
23	    #[serde(default)]
24	    pub version: Option<String>,
25	
26	    /// One-line description.
27	    pub description: String,
28	
29	    /// Search keywords beyond the name.
30	    #[serde(default)]
31	    pub keywords: Vec<String>,
32	
33	    /// Source code location and build info. Absent for MCP server manifests.
34	    #[serde(default)]
35	    pub source: Option<SourceSpec>,
36	
37	    /// Pre-built binary artifacts keyed by target triple.
38	    #[serde(default)]
39	    pub artifacts: std::collections::HashMap<String, ArtifactSpec>,
40	
41	    /// Summary of authentication requirements.
42	    #[serde(default)]
43	    pub auth_summary: Option<AuthSummary>,
44	
45	    /// Tags for filtering (e.g. "default", "messaging", "google").
46	    #[serde(default)]
47	    pub tags: Vec<String>,
48	
49	    /// MCP server URL. Only present for `McpServer` manifests.
50	    #[serde(default)]
51	    pub url: Option<String>,
52	
53	    /// MCP auth method: "dcr", "oauth_pre_configured:<setup_url>", or "none".
54	    /// Only present for `McpServer` manifests.
55	    #[serde(default)]
56	    pub auth: Option<String>,
57	}
58	
59	/// Extension kind as declared in manifests.
60	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
61	#[serde(rename_all = "snake_case")]
62	pub enum ManifestKind {
63	    Tool,
64	    Channel,
65	    McpServer,
66	}
