167	impl ExtensionManifest {
168	    /// Convert this manifest into a [`RegistryEntry`] for use with the in-chat
169	    /// extension discovery system.
170	    ///
171	    /// Returns `None` for MCP server manifests missing a `url` field.
172	    pub fn to_registry_entry(&self) -> Option<RegistryEntry> {
173	        if self.kind == ManifestKind::McpServer {
174	            return self.to_mcp_registry_entry();
175	        }
176	
177	        Some(self.to_wasm_registry_entry())
178	    }
179	
180	    /// Build a [`RegistryEntry`] for an MCP server manifest.
181	    fn to_mcp_registry_entry(&self) -> Option<RegistryEntry> {
182	        let url = match &self.url {
183	            Some(u) => u.clone(),
184	            None => {
185	                tracing::warn!(
186	                    "MCP server manifest '{}' is missing 'url' field, skipping",
187	                    self.name
188	                );
189	                return None;
190	            }
191	        };
192	        let auth_hint = match self.auth.as_deref() {
193	            Some("dcr") | None => AuthHint::Dcr,
194	            Some("none") => AuthHint::None,
195	            Some(other) if other.starts_with("oauth_pre_configured:") => {
196	                AuthHint::OAuthPreConfigured {
197	                    setup_url: other
198	                        .strip_prefix("oauth_pre_configured:")
199	                        .unwrap_or("")
200	                        .to_string(),
201	                }
202	            }
203	            _ => AuthHint::Dcr,
204	        };
205	
206	        Some(RegistryEntry {
207	            name: self.name.clone(),
208	            display_name: self.display_name.clone(),
209	            kind: ExtensionKind::McpServer,
210	            description: self.description.clone(),
211	            keywords: self.keywords.clone(),
212	            source: ExtensionSource::McpUrl { url },
213	            fallback_source: None,
214	            auth_hint,
215	            version: self.version.clone(),
216	        })
217	    }
218	
219	    /// Build a [`RegistryEntry`] for a WASM tool or channel manifest.
220	    fn to_wasm_registry_entry(&self) -> RegistryEntry {
221	        let source_spec = self.source.as_ref();
222	
223	        let buildable = source_spec.map(|s| ExtensionSource::WasmBuildable {
224	            source_dir: s.dir.clone(),
225	            build_dir: Some(s.dir.clone()),
226	            crate_name: Some(s.crate_name.clone()),
227	        });
228	
229	        // Prefer pre-built artifact download when a URL is available,
230	        // with build-from-source as fallback in case the download fails (e.g., 404).
231	        let (source, fallback_source) = if let Some(artifact) = self.artifacts.get("wasm32-wasip2")
232	        {
233	            if let Some(ref url) = artifact.url {
234	                (
235	                    ExtensionSource::WasmDownload {
236	                        wasm_url: url.clone(),
237	                        capabilities_url: artifact.capabilities_url.clone(),
238	                    },
239	                    buildable.map(Box::new),
240	                )
241	            } else if let Some(b) = buildable {
242	                (b, None)
243	            } else {
244	                // No source spec and no download URL — use a placeholder
245	                (
246	                    ExtensionSource::WasmBuildable {
247	                        source_dir: String::new(),
248	                        build_dir: None,
249	                        crate_name: None,
250	                    },
251	                    None,
252	                )
253	            }
254	        } else if let Some(b) = buildable {
255	            (b, None)
256	        } else {
257	            (
258	                ExtensionSource::WasmBuildable {
259	                    source_dir: String::new(),
260	                    build_dir: None,
261	                    crate_name: None,
262	                },
263	                None,
264	            )
265	        };
266	
267	        let auth_hint = match self.auth_summary.as_ref().and_then(|a| a.method.as_deref()) {
268	            Some("oauth") => AuthHint::CapabilitiesAuth,
269	            Some("manual") => AuthHint::CapabilitiesAuth,
270	            Some("none") | None => AuthHint::None,
271	            Some(_) => AuthHint::CapabilitiesAuth,
272	        };
273	
274	        RegistryEntry {
275	            name: self.name.clone(),
276	            display_name: self.display_name.clone(),
277	            kind: self.kind.into(),
278	            description: self.description.clone(),
279	            keywords: self.keywords.clone(),
280	            source,
281	            fallback_source,
282	            auth_hint,
283	            version: self.version.clone(),
284	        }
285	    }
286	}
