9	/// Error type for registry operations.
10	#[derive(Debug, thiserror::Error)]
11	pub enum RegistryError {
12	    #[error("Registry directory not found: {0}")]
13	    DirectoryNotFound(PathBuf),
14	
15	    #[error("Failed to read manifest {path}: {reason}")]
16	    ManifestRead { path: PathBuf, reason: String },
17	
18	    #[error("Failed to parse manifest {path}: {reason}")]
19	    ManifestParse { path: PathBuf, reason: String },
20	
21	    #[error("Extension not found: {0}")]
22	    ExtensionNotFound(String),
23	
24	    #[error("'{name}' already installed at {path}. Use --force to overwrite.")]
25	    AlreadyInstalled {
26	        name: String,
27	        path: std::path::PathBuf,
28	    },
29	
30	    // `url` is stored for programmatic access (logs, retries) but intentionally
31	    // omitted from the Display message to avoid leaking internal artifact URLs
32	    // to end users.
33	    #[error("Artifact download failed: {reason}")]
34	    DownloadFailed { url: String, reason: String },
35	
36	    #[error("Invalid extension manifest for '{name}' field '{field}': {reason}")]
37	    InvalidManifest {
38	        name: String,
39	        field: &'static str,
40	        reason: String,
41	    },
42	
43	    #[error("Checksum verification failed: expected {expected_sha256}, got {actual_sha256}")]
44	    ChecksumMismatch {
45	        url: String,
46	        expected_sha256: String,
47	        actual_sha256: String,
48	    },
49	
50	    #[error("Missing SHA256 checksum for '{name}' artifact. Use --build to build from source.")]
51	    MissingChecksum { name: String },
52	
53	    #[error(
54	        "Source fallback unavailable for '{name}' after artifact install failed. Retry artifact download or run from a repository checkout."
55	    )]
56	    SourceFallbackUnavailable {
57	        name: String,
58	        source_dir: PathBuf,
59	        artifact_error: Box<RegistryError>,
60	    },
61	
62	    #[error("Artifact install and source fallback both failed for '{name}'.")]
63	    InstallFallbackFailed {
64	        name: String,
65	        artifact_error: Box<RegistryError>,
66	        source_error: Box<RegistryError>,
67	    },
68	
69	    #[error(
70	        "Ambiguous name '{name}': exists as both {kind_a} and {kind_b}. Use '{prefix_a}/{name}' or '{prefix_b}/{name}'."
71	    )]
72	    AmbiguousName {
73	        name: String,
74	        kind_a: &'static str,
75	        prefix_a: &'static str,
76	        kind_b: &'static str,
77	        prefix_b: &'static str,
78	    },
79	
80	    #[error("Bundle not found: {0}")]
81	    BundleNotFound(String),
82	
83	    #[error("Failed to read bundles file: {0}")]
84	    BundlesRead(String),
85	
86	    #[error("IO error: {0}")]
87	    Io(#[from] std::io::Error),
88	}
