90	/// Central catalog loaded from the `registry/` directory.
91	#[derive(Debug, Clone)]
92	pub struct RegistryCatalog {
93	    /// All loaded manifests, keyed by "<kind>/<name>" (e.g. "tools/github").
94	    manifests: HashMap<String, ExtensionManifest>,
95	
96	    /// Bundle definitions from `_bundles.json`.
97	    bundles: HashMap<String, BundleDefinition>,
98	
99	    /// Root directory of the registry.
100	    root: PathBuf,
101	}
102	
103	impl RegistryCatalog {
104	    /// Find the `registry/` directory by searching relative to cwd, the executable,
105	    /// and `CARGO_MANIFEST_DIR`. Returns `None` if the directory cannot be found
106	    /// (non-fatal at startup).
107	    pub fn find_dir() -> Option<PathBuf> {
108	        // Try relative to current directory (for dev usage)
109	        if let Ok(cwd) = std::env::current_dir() {
110	            let candidate = cwd.join("registry");
111	            if candidate.is_dir() {
112	                return Some(candidate);
113	            }
114	        }
115	
116	        // Try relative to executable (covers installed binary, target/debug/, target/release/)
117	        if let Ok(exe) = std::env::current_exe()
118	            && let Some(parent) = exe.parent()
119	        {
120	            // Walk up to 3 levels: exe dir, parent (target/release -> target), grandparent (-> repo root)
121	            let mut dir = Some(parent);
122	            for _ in 0..3 {
123	                if let Some(d) = dir {
124	                    let candidate = d.join("registry");
125	                    if candidate.is_dir() {
126	                        return Some(candidate);
127	                    }
128	                    dir = d.parent();
129	                }
130	            }
131	        }
132	
133	        // Try CARGO_MANIFEST_DIR (compile-time, works in dev builds)
134	        let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
135	        let candidate = manifest_dir.join("registry");
136	        if candidate.is_dir() {
137	            return Some(candidate);
138	        }
139	
140	        None
141	    }
142	
143	    /// Try to load from disk; if `registry/` cannot be found, fall back to
144	    /// manifests embedded into the binary at compile time.
145	    pub fn load_or_embedded() -> Result<Self, RegistryError> {
146	        if let Some(dir) = Self::find_dir() {
147	            return Self::load(&dir);
148	        }
149	
150	        // Fall back to embedded catalog
151	        let manifests = embedded::load_embedded();
152	        let bundles = embedded::load_embedded_bundles();
153	
154	        tracing::info!(
155	            "Loaded embedded registry catalog ({} extensions, {} bundles)",
156	            manifests.len(),
157	            bundles.len()
158	        );
159	
160	        Ok(Self {
161	            manifests,
162	            bundles,
163	            root: PathBuf::new(),
164	        })
165	    }
166	
167	    /// Load the catalog from a registry directory.
168	    ///
169	    /// Expects the structure:
170	    /// ```text
171	    /// registry/
172	    /// ├── tools/*.json
173	    /// ├── channels/*.json
174	    /// └── _bundles.json
175	    /// ```
176	    pub fn load(registry_dir: &Path) -> Result<Self, RegistryError> {
177	        if !registry_dir.exists() {
178	            return Err(RegistryError::DirectoryNotFound(registry_dir.to_path_buf()));
179	        }
180	
181	        let mut manifests = HashMap::new();
182	
183	        // Load tools
184	        let tools_dir = registry_dir.join("tools");
185	        if tools_dir.is_dir() {
186	            Self::load_manifests_from_dir(&tools_dir, "tools", &mut manifests)?;
187	        }
188	
189	        // Load channels
190	        let channels_dir = registry_dir.join("channels");
191	        if channels_dir.is_dir() {
192	            Self::load_manifests_from_dir(&channels_dir, "channels", &mut manifests)?;
193	        }
194	
195	        // Load MCP servers
196	        let mcp_servers_dir = registry_dir.join("mcp-servers");
197	        if mcp_servers_dir.is_dir() {
198	            Self::load_manifests_from_dir(&mcp_servers_dir, "mcp-servers", &mut manifests)?;
199	        }
200	
201	        // Load bundles
202	        let bundles_path = registry_dir.join("_bundles.json");
203	        let bundles = if bundles_path.is_file() {
204	            let content = std::fs::read_to_string(&bundles_path).map_err(|e| {
205	                RegistryError::BundlesRead(format!("{}: {}", bundles_path.display(), e))
206	            })?;
207	            let bundles_file: BundlesFile = serde_json::from_str(&content).map_err(|e| {
208	                RegistryError::BundlesRead(format!("{}: {}", bundles_path.display(), e))
209	            })?;
210	            bundles_file.bundles
211	        } else {
212	            HashMap::new()
213	        };
214	
215	        Ok(Self {
216	            manifests,
217	            bundles,
218	            root: registry_dir.to_path_buf(),
219	        })
220	    }
221	
222	    fn load_manifests_from_dir(
223	        dir: &Path,
224	        kind_prefix: &str,
225	        manifests: &mut HashMap<String, ExtensionManifest>,
226	    ) -> Result<(), RegistryError> {
227	        let entries = std::fs::read_dir(dir).map_err(|e| RegistryError::ManifestRead {
228	            path: dir.to_path_buf(),
229	            reason: e.to_string(),
230	        })?;
231	
232	        for entry in entries {
233	            let entry = entry.map_err(|e| RegistryError::ManifestRead {
234	                path: dir.to_path_buf(),
235	                reason: e.to_string(),
236	            })?;
237	
238	            let path = entry.path();
239	            if !path.is_file() || path.extension().and_then(|e| e.to_str()) != Some("json") {
240	                continue;
241	            }
242	
243	            let content =
244	                std::fs::read_to_string(&path).map_err(|e| RegistryError::ManifestRead {
245	                    path: path.clone(),
246	                    reason: e.to_string(),
247	                })?;
248	
249	            let manifest: ExtensionManifest =
250	                serde_json::from_str(&content).map_err(|e| RegistryError::ManifestParse {
251	                    path: path.clone(),
252	                    reason: e.to_string(),
253	                })?;
254	
255	            let key = format!("{}/{}", kind_prefix, manifest.name);
256	            manifests.insert(key, manifest);
257	        }
258	
259	        Ok(())
260	    }
261	
262	    /// The root directory this catalog was loaded from.
263	    pub fn root(&self) -> &Path {
264	        &self.root
265	    }
