163	fn require_source(manifest: &ExtensionManifest) -> Result<&SourceSpec, RegistryError> {
164	    manifest
165	        .source
166	        .as_ref()
167	        .ok_or_else(|| RegistryError::InvalidManifest {
168	            name: manifest.name.clone(),
169	            field: "source",
170	            reason: "WASM extensions must have a source spec".to_string(),
171	        })
172	}
