553	    /// Install a single manifest, choosing build vs download based on artifact availability and flags.
554	    pub async fn install(
555	        &self,
556	        manifest: &ExtensionManifest,
557	        force: bool,
558	        prefer_build: bool,
559	    ) -> Result<InstallOutcome, RegistryError> {
560	        let has_artifact = manifest
561	            .artifacts
562	            .get("wasm32-wasip2")
563	            .and_then(|a| a.url.as_ref())
564	            .is_some();
565	
566	        if prefer_build || !has_artifact {
567	            self.install_from_source(manifest, force).await
568	        } else {
569	            self.install_with_source_fallback(manifest, force).await
570	        }
571	    }
