573	    /// Install all extensions in a bundle.
574	    /// Returns the outcomes and any shared auth hints.
575	    pub async fn install_bundle(
576	        &self,
577	        manifests: &[&ExtensionManifest],
578	        bundle: &BundleDefinition,
579	        force: bool,
580	        prefer_build: bool,
581	    ) -> (Vec<InstallOutcome>, Vec<String>) {
582	        let mut outcomes = Vec::new();
583	        let mut errors = Vec::new();
584	
585	        for manifest in manifests {
586	            match self.install(manifest, force, prefer_build).await {
587	                Ok(outcome) => outcomes.push(outcome),
588	                Err(e) => errors.push(format!("{}: {}", manifest.name, e)),
589	            }
590	        }
591	
592	        // Collect auth hints
593	        let mut auth_hints = Vec::new();
594	        if let Some(shared) = &bundle.shared_auth {
595	            auth_hints.push(format!(
596	                "Bundle uses shared auth '{}'. Run `ironclaw tool auth <any-member>` to authenticate all members.",
597	                shared
598	            ));
599	        }
600	
601	        // Collect unique auth providers that need setup
602	        let mut seen_providers = std::collections::HashSet::new();
603	        for manifest in manifests {
604	            if let Some(auth) = &manifest.auth_summary {
605	                let key = auth
606	                    .shared_auth
607	                    .as_deref()
608	                    .unwrap_or(manifest.name.as_str());
609	                if seen_providers.insert(key.to_string())
610	                    && let Some(url) = &auth.setup_url
611	                {
612	                    auth_hints.push(format!(
613	                        "  {} ({}): {}",
614	                        auth.provider.as_deref().unwrap_or(&manifest.name),
615	                        auth.method.as_deref().unwrap_or("manual"),
616	                        url
617	                    ));
618	                }
619	            }
620	        }
621	
622	        if !errors.is_empty() {
623	            auth_hints.push(format!(
624	                "\nFailed to install {} extension(s):",
625	                errors.len()
626	            ));
627	            for err in errors {
628	                auth_hints.push(format!("  - {}", err));
629	            }
630	        }
631	
632	        (outcomes, auth_hints)
633	    }
634	}
