636	/// Download an artifact from a URL.
637	async fn download_artifact(url: &str) -> Result<bytes::Bytes, RegistryError> {
638	    let response = reqwest::get(url)
639	        .await
640	        .map_err(|e| RegistryError::DownloadFailed {
641	            url: url.to_string(),
642	            reason: download_failure_reason(&e),
643	        })?;
644	
645	    let response = response
646	        .error_for_status()
647	        .map_err(|e| RegistryError::DownloadFailed {
648	            url: url.to_string(),
649	            reason: format!(
650	                "http status {}",
651	                e.status()
652	                    .map_or("unknown".to_string(), |status| status.as_u16().to_string())
653	            ),
654	        })?;
655	
656	    response
657	        .bytes()
658	        .await
659	        .map_err(|e| RegistryError::DownloadFailed {
660	            url: url.to_string(),
661	            reason: format!("failed to read response body: {}", e),
662	        })
663	}
664	
665	/// Verify SHA256 of downloaded bytes.
666	fn verify_sha256(bytes: &[u8], expected: &str, url: &str) -> Result<(), RegistryError> {
667	    use sha2::{Digest, Sha256};
668	    let mut hasher = Sha256::new();
669	    hasher.update(bytes);
670	    let actual = format!("{:x}", hasher.finalize());
671	
672	    if actual != expected {
673	        return Err(RegistryError::ChecksumMismatch {
674	            url: url.to_string(),
675	            expected_sha256: expected.to_string(),
676	            actual_sha256: actual,
677	        });
678	    }
679	    Ok(())
680	}
681	
682	/// Check if bytes start with gzip magic number (0x1f 0x8b).
683	fn is_gzip(bytes: &[u8]) -> bool {
684	    bytes.len() >= 2 && bytes[0] == 0x1f && bytes[1] == 0x8b
685	}
