1176	    // When a tool and channel share the same registry filename (e.g. slack.json),
1177	    // CI produces kind-prefixed bundles (tool-slack-*.tar.gz vs channel-slack-*.tar.gz).
1178	    // The files *inside* each archive use manifest.name (slack-tool.wasm vs slack.wasm).
1179	    // These tests verify the installer extracts by manifest.name correctly.
1180	
1181	    fn build_test_tar_gz(wasm_name: &str, caps_name: Option<&str>) -> Vec<u8> {
1182	        use flate2::Compression;
1183	        use flate2::write::GzEncoder;
1184	        use tar::Builder;
1185	
1186	        let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
1187	        {
1188	            let mut builder = Builder::new(&mut encoder);
1189	
1190	            let wasm_data = b"\0asm\x01\x00\x00\x00";
1191	            let mut header = tar::Header::new_gnu();
1192	            header.set_size(wasm_data.len() as u64);
1193	            header.set_cksum();
1194	            builder
1195	                .append_data(&mut header, wasm_name, &wasm_data[..])
1196	                .unwrap();
1197	
1198	            if let Some(caps) = caps_name {
1199	                let caps_data = br#"{"auth":null}"#;
1200	                let mut header = tar::Header::new_gnu();
1201	                header.set_size(caps_data.len() as u64);
1202	                header.set_cksum();
1203	                builder
1204	                    .append_data(&mut header, caps, &caps_data[..])
1205	                    .unwrap();
1206	            }
1207	
1208	            builder.finish().unwrap();
1209	        }
1210	        encoder.finish().unwrap()
1211	    }
