116	/// Collect all registry manifests into a single JSON blob at compile time.
117	///
118	/// Output: `$OUT_DIR/embedded_catalog.json` with structure:
119	/// ```json
120	/// { "tools": [...], "channels": [...], "bundles": {...} }
121	/// ```
122	fn embed_registry_catalog(root: &Path) {
123	    use std::fs;
124	
125	    let registry_dir = root.join("registry");
126	
127	    // Rerun if the bundles file changes (per-file watches for tools/channels
128	    // are emitted inside collect_json_files to track content changes reliably).
129	    println!("cargo:rerun-if-changed=registry/_bundles.json");
130	
131	    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
132	    let out_path = out_dir.join("embedded_catalog.json");
133	
134	    if !registry_dir.is_dir() {
135	        // No registry dir: write empty catalog
136	        fs::write(
137	            &out_path,
138	            r#"{"tools":[],"channels":[],"mcp_servers":[],"bundles":{"bundles":{}}}"#,
139	        )
140	        .unwrap();
141	        return;
142	    }
143	
144	    let mut tools = Vec::new();
145	    let mut channels = Vec::new();
146	    let mut mcp_servers = Vec::new();
147	
148	    // Collect tool manifests
149	    let tools_dir = registry_dir.join("tools");
150	    if tools_dir.is_dir() {
151	        collect_json_files(&tools_dir, &mut tools);
152	    }
153	
154	    // Collect channel manifests
155	    let channels_dir = registry_dir.join("channels");
156	    if channels_dir.is_dir() {
157	        collect_json_files(&channels_dir, &mut channels);
158	    }
159	
160	    // Collect MCP server manifests
161	    let mcp_servers_dir = registry_dir.join("mcp-servers");
162	    if mcp_servers_dir.is_dir() {
163	        collect_json_files(&mcp_servers_dir, &mut mcp_servers);
164	    }
165	
166	    // Read bundles
167	    let bundles_path = registry_dir.join("_bundles.json");
168	    let bundles_raw = if bundles_path.is_file() {
169	        fs::read_to_string(&bundles_path).unwrap_or_else(|_| r#"{"bundles":{}}"#.to_string())
170	    } else {
171	        r#"{"bundles":{}}"#.to_string()
172	    };
173	
174	    // Build the combined JSON
175	    let catalog = format!(
176	        r#"{{"tools":[{}],"channels":[{}],"mcp_servers":[{}],"bundles":{}}}"#,
177	        tools.join(","),
178	        channels.join(","),
179	        mcp_servers.join(","),
180	        bundles_raw,
181	    );
182	
183	    fs::write(&out_path, catalog).unwrap();
184	}
