186	/// Collect all `skills/*/SKILL.md` files into an embedded JSON blob.
187	///
188	/// Output: `$OUT_DIR/embedded_skills.json` — a JSON array of `{"name": "...", "content": "..."}`.
189	/// These are loaded at runtime as bundled skills (lowest discovery priority, Trusted trust level).
190	fn embed_skills(root: &Path) {
191	    use std::fs;
192	
193	    let skills_dir = root.join("skills");
194	
195	    // Rerun when any skill changes
196	    println!("cargo:rerun-if-changed=skills");
197	
198	    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap()); // safety: build script panics on failure
199	    let out_path = out_dir.join("embedded_skills.json");
200	
201	    if !skills_dir.is_dir() {
202	        fs::write(&out_path, "[]").unwrap(); // safety: build script
203	        return;
204	    }
205	
206	    let mut skills: Vec<String> = Vec::new();
207	
208	    let mut entries: Vec<_> = fs::read_dir(&skills_dir)
209	        .unwrap() // safety: build script
210	        .filter_map(|e| e.ok())
211	        .filter(|e| e.path().is_dir())
212	        .collect();
213	    entries.sort_by_key(|e| e.file_name());
214	
215	    for entry in entries {
216	        let skill_md = entry.path().join("SKILL.md");
217	        if !skill_md.is_file() {
218	            continue;
219	        }
220	        // Emit per-file watch
221	        println!("cargo:rerun-if-changed={}", skill_md.display());
222	
223	        let name = entry.file_name().to_string_lossy().to_string();
224	        if let Ok(content) = fs::read_to_string(&skill_md) {
225	            // Escape for JSON embedding
226	            let name_json = serde_json::to_string(&name).unwrap(); // safety: build script
227	            let content_json = serde_json::to_string(&content).unwrap(); // safety: build script
228	            skills.push(format!(
229	                r#"{{"name":{},"content":{}}}"#,
230	                name_json, content_json
231	            ));
232	        }
233	    }
234	
235	    let catalog = format!("[{}]", skills.join(","));
236	    fs::write(&out_path, catalog).unwrap(); // safety: build script
237	}
238	
239	/// Read all .json files from a directory and push their raw contents into `out`.
240	fn collect_json_files(dir: &Path, out: &mut Vec<String>) {
241	    use std::fs;
242	
243	    let mut entries: Vec<_> = fs::read_dir(dir)
244	        .unwrap()
245	        .filter_map(|e| e.ok())
246	        .filter(|e| {
247	            e.path().is_file() && e.path().extension().and_then(|x| x.to_str()) == Some("json")
248	        })
249	        .collect();
250	
251	    // Sort for deterministic output
252	    entries.sort_by_key(|e| e.file_name());
253	
254	    for entry in entries {
255	        // Emit per-file watch so Cargo reruns when file contents change
256	        println!("cargo:rerun-if-changed={}", entry.path().display());
257	        if let Ok(content) = fs::read_to_string(entry.path()) {
258	            out.push(content);
259	        }
260	    }
261	}
