1	//! Unified WASM artifact resolution: find, build, and install WASM components.
2	//!
3	//! This module consolidates all WASM artifact logic that was previously duplicated
4	//! across `cli/tool.rs`, `registry/installer.rs`, `extensions/manager.rs`,
5	//! `channels/wasm/bundled.rs`, and `tools/wasm/loader.rs`.
6	//!
7	//! # Functions
8	//!
9	//! - [`resolve_target_dir`] — resolve the cargo target directory for a crate
10	//! - [`find_wasm_artifact`] — find a compiled `.wasm` by crate name across all triples
11	//! - [`find_any_wasm_artifact`] — find any `.wasm` file (fallback when name is unknown)
12	//! - [`build_wasm_component`] — async build via `cargo component build`
13	//! - [`build_wasm_component_sync`] — sync build for CLI use
14	//! - [`install_wasm_files`] — copy `.wasm` + optional `.capabilities.json` to install dir
15	
16	use std::path::{Path, PathBuf};
17	
18	use tokio::fs;
19	
20	/// WASM target triples to search, in priority order.
21	const WASM_TRIPLES: &[&str] = &[
22	    "wasm32-wasip1",
23	    "wasm32-wasip2",
24	    "wasm32-wasi",
25	    "wasm32-unknown-unknown",
26	];
27	
28	/// Resolve the cargo target directory for a crate.
29	///
30	/// Checks (in order):
31	/// 1. `CARGO_TARGET_DIR` env var (shared target dir)
32	/// 2. `<crate_dir>/target/` (default per-crate layout)
33	pub fn resolve_target_dir(crate_dir: &Path) -> PathBuf {
34	    if let Ok(dir) = std::env::var("CARGO_TARGET_DIR") {
35	        let p = PathBuf::from(dir);
36	        // Resolve relative CARGO_TARGET_DIR against crate_dir
37	        if p.is_relative() {
38	            return crate_dir.join(p);
39	        }
40	        return p;
41	    }
42	    crate_dir.join("target")
43	}
44	
45	/// Find a compiled WASM artifact by searching across all target triples.
46	///
47	/// Tries exact name match first (with hyphen-to-underscore normalization),
48	/// then falls back to searching in whichever target directory exists.
49	/// `profile` is `"release"` or `"debug"`.
50	pub fn find_wasm_artifact(crate_dir: &Path, crate_name: &str, profile: &str) -> Option<PathBuf> {
51	    let target_base = resolve_target_dir(crate_dir);
52	    let snake_name = crate_name.replace('-', "_");
53	
54	    // Try exact name match in each target triple directory
55	    for triple in WASM_TRIPLES {
56	        let dir = target_base.join(triple).join(profile);
57	        let candidates = [
58	            dir.join(format!("{}.wasm", crate_name)),
59	            dir.join(format!("{}.wasm", snake_name)),
60	        ];
61	        for candidate in &candidates {
62	            if candidate.exists() {
63	                return Some(candidate.clone());
64	            }
65	        }
66	    }
67	
68	    None
69	}
70	
71	/// Find any `.wasm` file in the target dirs (fallback when crate name is unknown).
72	///
73	/// Returns the first `.wasm` found across target triples.
74	pub fn find_any_wasm_artifact(crate_dir: &Path, profile: &str) -> Option<PathBuf> {
75	    let target_base = resolve_target_dir(crate_dir);
76	
77	    for triple in WASM_TRIPLES {
78	        let dir = target_base.join(triple).join(profile);
79	        if !dir.is_dir() {
80	            continue;
81	        }
82	        if let Ok(entries) = std::fs::read_dir(&dir) {
83	            for entry in entries.flatten() {
84	                let path = entry.path();
85	                if path.extension().map(|ext| ext == "wasm").unwrap_or(false) {
86	                    return Some(path);
87	                }
88	            }
89	        }
90	    }
91	
92	    None
93	}
