124	    // Use status() with inherited stdio so build output streams to the terminal.
125	    let status = cmd.status().await?;
126	
127	    if !status.success() {
128	        anyhow::bail!("Build failed (exit code: {})", status);
129	    }
130	
131	    let profile = if release { "release" } else { "debug" };
132	    let wasm_filename = format!("{}.wasm", crate_name.replace('-', "_"));
133	
134	    // Look for the specific crate's WASM file across target triples
135	    find_wasm_artifact(source_dir, wasm_filename.trim_end_matches(".wasm"), profile)
136	        .or_else(|| {
137	            // Fall back: search by crate_name directly
138	            find_wasm_artifact(source_dir, crate_name, profile)
139	        })
140	        .or_else(|| find_any_wasm_artifact(source_dir, profile))
141	        .ok_or_else(|| {
142	            anyhow::anyhow!(
143	                "Could not find {} in {}/target/*/{}/ after build",
144	                wasm_filename,
145	                source_dir.display(),
146	                profile,
147	            )
148	        })
149	}
150	
151	/// Build a WASM component using `cargo-component` (sync, for CLI use).
152	///
153	/// Returns the path to the built artifact.
154	pub fn build_wasm_component_sync(source_dir: &Path, release: bool) -> anyhow::Result<PathBuf> {
155	    use std::process::Command;
156	
157	    println!("Building WASM component in {}...", source_dir.display());
158	
159	    // Check if cargo-component is available
160	    let check = Command::new("cargo")
161	        .args(["component", "--version"])
162	        .output();
163	
164	    if check.is_err() || !check.as_ref().map(|o| o.status.success()).unwrap_or(false) {
165	        anyhow::bail!(
166	            "cargo-component not found. Install with: cargo install cargo-component\n\
167	             Or use --skip-build with an existing .wasm file."
168	        );
169	    }
170	
171	    let mut cmd = Command::new("cargo");
172	    cmd.current_dir(source_dir).args(["component", "build"]);
173	
174	    if release {
175	        cmd.arg("--release");
176	    }
177	
178	    println!(
179	        "  Running: cargo component build{}",
180	        if release { " --release" } else { "" }
181	    );
182	
183	    let output = cmd.output()?;
184	
185	    if !output.status.success() {
186	        let stderr = String::from_utf8_lossy(&output.stderr);
187	        anyhow::bail!("Build failed:\n{}", stderr);
188	    }
189	
190	    let profile = if release { "release" } else { "debug" };
191	
192	    // Find the built artifact
193	    find_any_wasm_artifact(source_dir, profile).ok_or_else(|| {
194	        anyhow::anyhow!(
195	            "No .wasm file found after build in {}/target/*/{}",
196	            source_dir.display(),
197	            profile,
198	        )
199	    })
200	}

1	//! Embedded registry catalog compiled into the binary at build time.
2	//!
3	//! When IronClaw is distributed as a pre-built binary without a source tree,
4	//! the `registry/` directory is unavailable. This module provides the same
5	//! manifest data via `include_str!` from a JSON blob generated by `build.rs`.
6	
7	use std::collections::HashMap;
8	use std::sync::OnceLock;
9	
10	use crate::registry::manifest::{BundleDefinition, BundlesFile, ExtensionManifest};
11	
12	/// Raw JSON generated by build.rs from `registry/{tools,channels}/*.json` and `_bundles.json`.
13	const EMBEDDED_CATALOG: &str = include_str!(concat!(env!("OUT_DIR"), "/embedded_catalog.json"));
14	
15	/// Intermediate deserialization shape matching the build.rs output.
16	#[derive(serde::Deserialize)]
17	struct EmbeddedCatalogRaw {
18	    #[serde(default)]
19	    tools: Vec<ExtensionManifest>,
20	    #[serde(default)]
21	    channels: Vec<ExtensionManifest>,
22	    #[serde(default)]
23	    mcp_servers: Vec<ExtensionManifest>,
24	    #[serde(default)]
25	    bundles: BundlesFile,
26	}
27	
28	/// Parsed catalog cached across calls.
29	struct ParsedCatalog {
30	    manifests: HashMap<String, ExtensionManifest>,
31	    bundles: HashMap<String, BundleDefinition>,
32	}
33	
34	fn parsed_catalog() -> &'static ParsedCatalog {
35	    static CACHE: OnceLock<ParsedCatalog> = OnceLock::new();
36	    CACHE.get_or_init(|| {
37	        let raw: EmbeddedCatalogRaw = match serde_json::from_str(EMBEDDED_CATALOG) {
38	            Ok(v) => v,
39	            Err(e) => {
40	                tracing::warn!("Failed to parse embedded catalog: {}", e);
41	                return ParsedCatalog {
42	                    manifests: HashMap::new(),
43	                    bundles: HashMap::new(),
44	                };
45	            }
46	        };
47	
48	        let mut manifests = HashMap::new();
49	        for m in raw.tools {
50	            let key = format!("tools/{}", m.name);
51	            manifests.insert(key, m);
52	        }
53	        for m in raw.channels {
54	            let key = format!("channels/{}", m.name);
55	            manifests.insert(key, m);
56	        }
57	        for m in raw.mcp_servers {
58	            let key = format!("mcp-servers/{}", m.name);
59	            manifests.insert(key, m);
60	        }
61	
62	        ParsedCatalog {
63	            manifests,
64	            bundles: raw.bundles.bundles,
65	        }
66	    })
67	}
68	
69	/// Load all embedded extension manifests, keyed by `"tools/<name>"` or `"channels/<name>"`.
70	pub fn load_embedded() -> HashMap<String, ExtensionManifest> {
71	    parsed_catalog().manifests.clone()
72	}
73	
74	/// Load embedded bundle definitions.
75	pub fn load_embedded_bundles() -> HashMap<String, BundleDefinition> {
76	    parsed_catalog().bundles.clone()
77	}
78	
79	#[cfg(test)]
80	mod tests {
81	    use super::*;
82	
83	    #[test]
84	    fn test_load_embedded_parses() {
85	        let manifests = load_embedded();
86	        // Should have at least the manifests from registry/ if built from the repo
87	        // (empty is also valid for minimal builds without registry/)
88	        assert!(
89	            manifests.is_empty() || manifests.contains_key("tools/github"),
90	            "Expected either empty catalog or github tool, got {} entries",
91	            manifests.len()
92	        );
93	    }
94	
