1	//! Known WASM channels that can be installed from build artifacts.
2	//!
3	//! Instead of embedding WASM binaries in the host binary via include_bytes!,
4	//! channels are compiled separately and installed from their build output
5	//! directories during onboarding.
6	//!
7	//! Channel source layout:
8	//!   channels-src/<name>/
9	//!     target/wasm32-wasip2/release/<name>_channel.wasm
10	//!     <name>.capabilities.json
11	
12	use std::path::{Path, PathBuf};
13	
14	use tokio::fs;
15	
16	/// Compile-time project root, used to locate channels-src/ in dev builds.
17	const CARGO_MANIFEST_DIR: &str = env!("CARGO_MANIFEST_DIR");
18	
19	/// Known channel names and their crate names (for locating build artifacts).
20	const KNOWN_CHANNELS: &[(&str, &str)] = &[
21	    ("telegram", "telegram_channel"),
22	    ("slack", "slack_channel"),
23	    ("discord", "discord_channel"),
24	    ("whatsapp", "whatsapp_channel"),
25	    ("feishu", "feishu_channel"),
26	    ("xmpp", "xmpp_channel"),
27	];
28	
29	/// Names of known channels that can be installed.
30	pub fn bundled_channel_names() -> Vec<&'static str> {
31	    KNOWN_CHANNELS.iter().map(|(name, _)| *name).collect()
32	}
33	
34	/// Resolve the channels source directory.
35	///
36	/// Checks (in order):
37	/// 1. `IRONCLAW_CHANNELS_SRC` env var
38	/// 2. `<CARGO_MANIFEST_DIR>/channels-src/` (dev builds)
39	fn channels_src_dir() -> PathBuf {
40	    if let Ok(dir) = std::env::var("IRONCLAW_CHANNELS_SRC") {
41	        return PathBuf::from(dir);
42	    }
43	    PathBuf::from(CARGO_MANIFEST_DIR).join("channels-src")
44	}
45	
46	/// Locate the build artifacts for a channel.
47	///
48	/// Checks two layouts:
49	/// 1. **Flat** (Docker/packaged): `<channels_src>/<name>/<name>.wasm`
50	/// 2. **Build tree** (dev): `<channels_src>/<name>/target/wasm32-wasip2/release/<crate_name>.wasm`
51	///
52	/// Returns (wasm_path, capabilities_path) or an error if files are missing.
53	fn locate_channel_artifacts(name: &str) -> Result<(PathBuf, PathBuf), String> {
54	    let (_, crate_name) = KNOWN_CHANNELS
55	        .iter()
56	        .find(|(n, _)| *n == name)
57	        .ok_or_else(|| format!("Unknown channel '{}'", name))?;
58	
59	    let src_dir = channels_src_dir();
60	    let channel_dir = src_dir.join(name);
61	
62	    let caps_path = channel_dir.join(format!("{}.capabilities.json", name));
63	
64	    // Check flat layout first (Docker/packaged deployments)
65	    let flat_wasm = channel_dir.join(format!("{}.wasm", name));
66	    if flat_wasm.exists() && caps_path.exists() {
67	        return Ok((flat_wasm, caps_path));
68	    }
69	
70	    // Fall back to build tree layout (dev builds) — search across all WASM triples
71	    if let Some(build_wasm) =
72	        crate::registry::artifacts::find_wasm_artifact(&channel_dir, crate_name, "release")
73	        && caps_path.exists()
74	    {
75	        return Ok((build_wasm, caps_path));
76	    }
77	
78	    // Provide a helpful error with the paths we checked
79	    let expected_build = crate::registry::artifacts::resolve_target_dir(&channel_dir)
80	        .join("wasm32-wasip2/release")
81	        .join(format!("{}.wasm", crate_name));
82	
83	    Err(format!(
84	        "Channel '{}' WASM not found. Checked:\n  \
85	         - {} (flat/packaged)\n  \
86	         - {} (build tree, and other triples)\n  \
87	         Build it first:\n  \
88	         cd {} && cargo component build --release",
89	        name,
90	        flat_wasm.display(),
91	        expected_build.display(),
92	        channel_dir.display()
93	    ))
94	}
95	
96	/// Install a channel from build artifacts into the channels directory.
97	pub async fn install_bundled_channel(
98	    name: &str,
99	    target_dir: &Path,
100	    force: bool,
101	) -> Result<(), String> {
102	    let (wasm_src, caps_src) = locate_channel_artifacts(name)?;
103	
104	    fs::create_dir_all(target_dir)
105	        .await
106	        .map_err(|e| format!("Failed to create channels directory: {}", e))?;
107	
108	    let wasm_dst = target_dir.join(format!("{}.wasm", name));
109	    let caps_dst = target_dir.join(format!("{}.capabilities.json", name));
110	
111	    let has_existing = wasm_dst.exists() || caps_dst.exists();
112	    if has_existing && !force {
113	        return Err(format!(
114	            "Channel '{}' already exists at {}",
115	            name,
116	            target_dir.display()
117	        ));
118	    }
119	
120	    fs::copy(&wasm_src, &wasm_dst)
121	        .await
122	        .map_err(|e| format!("Failed to copy {}: {}", wasm_src.display(), e))?;
123	    fs::copy(&caps_src, &caps_dst)
124	        .await
125	        .map_err(|e| format!("Failed to copy {}: {}", caps_src.display(), e))?;
126	
127	    Ok(())
128	}
129	
130	/// Check which known channels have build artifacts available.
131	pub fn available_channel_names() -> Vec<&'static str> {
132	    KNOWN_CHANNELS
133	        .iter()
134	        .filter(|(name, _)| locate_channel_artifacts(name).is_ok())
135	        .map(|(name, _)| *name)
136	        .collect()
137	}
